  library(readxl)
  library(fs)
load_ntd_energy &lt;- function(){

  # Create 'data/mp02' directory if not already present
  DATA_DIR &lt;- fs::path("data", "mp02")
  fs::dir_create(DATA_DIR, recurse=TRUE)

  NTD_ENERGY_FILE &lt;- fs::path(DATA_DIR, "2025_ntd_energy.xlsx")

  if(!fs::file_exists(NTD_ENERGY_FILE)){
    library(httr2)

    request("https://www.transit.dot.gov/") |&gt;
      req_url_path("sites",
                   "fta.dot.gov",
                   "files",
                   "2026-09",
                   "2025 Energy Consumption_260806.xlsx") |&gt; 
      req_headers(
        `User-Agent` = "Mozilla/5.0 (Macintosh; Intel Mac OS X 10.15; rv:149.0) Gecko/20100101 Firefox/149.0") |&gt; 
      req_perform(NTD_ENERGY_FILE)
  }

  if(file.info(NTD_ENERGY_FILE)$size &lt; 1e4){
    cat("I was unable to download the NTD Energy File. Please try again.\n")
    stop("Download failed. Please delete the corrupted file by running `unlink('data/mp02/2025_ntd_energy.xlsx')` and try again.")
  }

  to_numeric_fill_0 &lt;- function(x){
    x &lt;- if_else(x == "-", NA, x)
    replace_na(as.numeric(x), 0)
  }

  read_excel(NTD_ENERGY_FILE) |&gt; 
    select(-c(`Reporter Type`, 
              `Reporting Module`, 
              `Gallons of Other Fuel`, 
              `Other Fuel Description`)) |&gt;
    mutate(across(-c(`Agency Name`, 
                     `Mode`,
                     `TOS`), 
                  to_numeric_fill_0)) |&gt;
    group_by(`NTD ID`, `Mode`, `Agency Name`) |&gt;
    summarize(across(where(is.numeric), sum), 
              .groups = "keep") |&gt;
    mutate(ENERGY = sum(c_across(c(where(is.numeric))))) |&gt;
    filter(ENERGY &gt; 0) |&gt;
    select(-ENERGY) |&gt;
    ungroup()
}

NTD_ENERGY &lt;- load_ntd_energy()

